@Component("warranty-subscriber")
public class WarrantySubscriber extends BaseSubscriber {

	public WarrantySubscriber() {
	}
	
    public SubscriptionQueryResult<List<Warranty>, Warranty> warrantySubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllWarrantyQuery(), 
                		ResponseTypes.multipleInstancesOf(Warranty.class),
                		ResponseTypes.instanceOf(Warranty.class));
    }

    public SubscriptionQueryResult<Warranty, Warranty> warrantySubscribe(@DestinationVariable UUID warrantyId) {
        return queryGateway
                .subscriptionQuery(new FindWarrantyQuery(new LoadWarrantyFilter(warrantyId)), 
                		ResponseTypes.instanceOf(Warranty.class),
                		ResponseTypes.instanceOf(Warranty.class));
    }





}

